    "searchByNameOr5l10l": "Search by name, or paste",
    "searchHuggingFaceReuse12nau": "Search Hugging Face, reuse a model already on this device, or paste",
    "searchTheHubOr1hf31": "Search the Hub, or upload PDF, DOCX, JSONL, JSON, CSV or Parquet. Preview a few rows before you start, since formatting matters more than size. We map the columns for you and ask only when the format is unclear. No dataset yet? Build one on the Recipes page.",
    "sensibleHyperparametersSmallerModeerr7z": "sensible hyperparameters. Smaller models iterate faster, so scale up once the data looks right. GGUF files cannot be trained.",
    "simpleCoversEpochsLearning5tnd7": "Simple covers epochs, learning rate, batch size and context length. Advanced opens LoRA rank, schedulers, eval and checkpointing. Defaults come from the model you picked, so change one knob at a time. 1 to 3 epochs is a good start.",
    "someModelsNeedThe2qk5z": "Some models need the clip's words to match its voice. Type them or press Transcribe.",
    "sourceSeparationModels7i1a0": "Source separation models.",
    "speechRecognitionModelsThey1p9vq": "Speech recognition models. They run beside your chat model, not in its place.",
    "textToSpeechModelse4pii": "Text-to-speech models, including voices you fine-tuned under On Device.",
    "theSelectedClipPlays12tt9": "The selected clip plays here and every clip lines up below. Download it, or reuse its settings for the next run.",
